def check_running(self):
        """
        Check if a pid file exists and if it is associated with
        a running process.
        """
        if not os.path.exists(self.pid_file):
            return False
        pid = int(open(self.pid_file).read())
        if not pid:
            return False
        if not os.path.exists("/proc/%s" % pid):
            return False
        return True

